package live.linghe.privateinput;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.view.*;import android.view.inputmethod.*;import android.widget.*;import android.graphics.Color;import android.text.InputType;

public final class MainActivity extends Activity {
 private LinearLayout content;private android.content.SharedPreferences prefs;private EditText test;private TextView status,layoutValue,heightValue,inlineValue,feedbackValue;
 private String versionName(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception ignored){return "";}}
 private void openLicenses(){
  StringBuilder value=new StringBuilder("灵鹤输入法使用Rime、公开词典与本机搭配模型。对应来源和许可随包保留。词典对应源码：https://support.example.invalid/apps/linghe-input/support/\n\n");
  try{for(String folder:new String[]{"licenses","rime/licenses"})for(String name:getAssets().list(folder)){value.append("\n===== ").append(name).append(" =====\n");try(java.io.InputStream in=getAssets().open(folder+"/"+name)){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int count;while((count=in.read(buffer))>0)bytes.write(buffer,0,count);value.append(bytes.toString("UTF-8"));}}}catch(java.io.IOException error){value.append("许可读取失败，请访问支持页面查看。");}
  TextView body=text(value.toString(),14,Ui.text(this));body.setTextIsSelectable(true);body.setPadding(dp(20),dp(12),dp(20),dp(12));ScrollView scroll=new ScrollView(this);scroll.addView(body);new AlertDialog.Builder(this).setTitle("开源许可").setView(scroll).setPositiveButton("好",null).show();
 }
 private int dp(float v){return Ui.dp(this,v);}
 private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);return t;}
 private static final String HOME="home",INPUT="input",APPEARANCE="appearance",WORDS="words",TRY="try",ABOUT="about";
 private String page=HOME,trialDraft="";private int trialSelection;private Button activate;private Object pageBack;
 @Override public void onCreate(Bundle state){Ui.prepareTheme(this);super.onCreate(state);prefs=getSharedPreferences("keyboard",0);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
  if(state!=null){page=state.getString("settings-page",HOME);trialDraft=state.getString("trial-draft","");trialSelection=state.getInt("trial-selection",trialDraft.length());}showPage(page);
 }
 private void rememberTrial(){if(test!=null){trialDraft=test.getText().toString();trialSelection=test.getSelectionStart();}}
 @Override protected void onSaveInstanceState(Bundle state){rememberTrial();state.putString("settings-page",page);state.putString("trial-draft",trialDraft);state.putInt("trial-selection",trialSelection);super.onSaveInstanceState(state);}
 private void showPage(String next){rememberTrial();if(test!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(test.getWindowToken(),0);SettingsScreen.releaseBack(this,pageBack);pageBack=null;page=next;test=null;status=null;activate=null;layoutValue=null;heightValue=null;inlineValue=null;feedbackValue=null;
  String title=INPUT.equals(page)?"输入设置":APPEARANCE.equals(page)?"外观":WORDS.equals(page)?"词库与学习":TRY.equals(page)?"试打":ABOUT.equals(page)?"帮助与关于":"灵鹤输入法";
  content=SettingsScreen.content(this,title,!HOME.equals(page));
  if(INPUT.equals(page))inputPage();else if(APPEARANCE.equals(page))appearancePage();else if(WORDS.equals(page))wordsPage();else if(TRY.equals(page))trialPage();else if(ABOUT.equals(page))aboutPage();else{page=HOME;homePage();}
  if(!HOME.equals(page))pageBack=SettingsScreen.interceptBack(this,()->showPage(HOME));
 }
 private void homePage(){
  LinearLayout setup=new LinearLayout(this);setup.setOrientation(LinearLayout.VERTICAL);content.addView(setup,new LinearLayout.LayoutParams(-1,-2));LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(dp(4),dp(4),0,dp(4));
  ImageView icon=new ImageView(this);icon.setImageResource(live.linghe.privateinput.R.drawable.app_icon);icon.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);line.addView(icon,new LinearLayout.LayoutParams(dp(32),dp(32)));
  status=text("",15,Ui.text(this));LinearLayout.LayoutParams statusSize=new LinearLayout.LayoutParams(0,-2,1);statusSize.setMargins(dp(12),0,dp(8),0);line.addView(status,statusSize);
  activate=new Button(this);activate.setAllCaps(false);activate.setTextColor(Ui.accent(this));activate.setTextSize(14);activate.setMinWidth(0);activate.setMinimumWidth(0);activate.setPadding(dp(10),0,dp(10),0);Ui.pressable(activate,Ui.surface(this),8);activate.setOnClickListener(v->{if(enabled())((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showInputMethodPicker();else startActivity(new Intent(Settings.ACTION_INPUT_METHOD_SETTINGS));});line.addView(activate,new LinearLayout.LayoutParams(-2,dp(48)));setup.addView(line);refreshKeyboardStatus();
  LinearLayout navigation=section(null);row(navigation,"输入设置",prefs.getBoolean("nine",true)?"九宫格":"26 键",()->showPage(INPUT));row(navigation,"外观","",()->showPage(APPEARANCE));row(navigation,"词库与学习","",()->showPage(WORDS));row(navigation,"设备与同步","",()->startActivity(new Intent(this,DeviceSyncActivity.class)));row(navigation,"隐私与归档","",()->startActivity(new Intent(this,ActivityArchiveActivity.class)));
  LinearLayout secondary=section(null);row(secondary,"试打","",()->showPage(TRY));row(secondary,"帮助与关于","",()->showPage(ABOUT));
 }
 private Switch toggle(LinearLayout box,String title,String key,boolean fallback){Switch value=new Switch(this);value.setText(title);value.setTextSize(16);value.setTextColor(Ui.text(this));value.setPadding(dp(16),dp(8),dp(16),dp(8));value.setMinHeight(dp(52));value.setChecked(prefs.getBoolean(key,fallback));value.setOnCheckedChangeListener((view,on)->prefs.edit().putBoolean(key,on).apply());box.addView(value,new LinearLayout.LayoutParams(-1,-2));return value;}
 private void inputPage(){
  LinearLayout layout=section("布局");layoutValue=row(layout,"中文布局",prefs.getBoolean("nine",true)?"九宫格":"26 键",this::chooseLayout);heightValue=row(layout,"键盘高度",prefs.getInt("height",58)+"",this::heightDialog);inlineValue=row(layout,"拼音显示位置",prefs.getBoolean("inline",false)?"文本框内":"键盘内",this::choosePosition);feedbackValue=row(layout,"按键触感",feedbackLabel(),this::chooseFeedback);row(layout,"常用符号","",this::symbolsDialog);
  LinearLayout suggestions=section("输入辅助");toggle(suggestions,"中英混输","mixed",true);toggle(suggestions,"上下文联想","context",true);toggle(suggestions,"英文补全","english-completion",true);
  LinearLayout symbols=section("符号与光标");toggle(symbols,"符号自动成对","symbol-auto-pair",true);toggle(symbols,"光标放在符号中间","symbol-caret-inside",true);
 }
 private void appearancePage(){LinearLayout appearance=section(null);row(appearance,"明暗模式",InputTheme.MODE_TITLES[InputTheme.index(InputTheme.MODES,Ui.mode(this))],()->choice("明暗模式",InputTheme.MODE_TITLES,InputTheme.index(InputTheme.MODES,Ui.mode(this)),index->{prefs.edit().putString("appearance-mode",InputTheme.MODES[index]).commit();recreate();}));row(appearance,"主题色",InputTheme.ACCENT_TITLES[InputTheme.index(InputTheme.ACCENTS,Ui.accentName(this))],()->choice("主题色",InputTheme.ACCENT_TITLES,InputTheme.index(InputTheme.ACCENTS,Ui.accentName(this)),index->{prefs.edit().putString("appearance-accent",InputTheme.ACCENTS[index]).commit();recreate();}));}
 private void wordsPage(){LinearLayout words=section(null);row(words,"个人词库与快捷短语","",()->startActivity(new Intent(this,PersonalLexiconActivity.class)));toggle(words,"学习常用词","learning",true);}
 private void trialPage(){LinearLayout typing=section(null);test=new EditText(this);test.setId(1001);test.setHint("试试输入你想说的话");test.setTextColor(Ui.text(this));test.setHintTextColor(Ui.muted(this));test.setTextSize(19);test.setGravity(Gravity.TOP|Gravity.START);test.setPadding(dp(16),dp(14),dp(16),dp(14));test.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);test.setImeOptions(EditorInfo.IME_ACTION_NONE|EditorInfo.IME_FLAG_NO_ENTER_ACTION|EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);test.setMinLines(3);test.setBackgroundColor(Color.TRANSPARENT);test.setText(trialDraft);test.setSelection(Math.max(0,Math.min(trialDraft.length(),trialSelection)));typing.addView(test,new LinearLayout.LayoutParams(-1,-2));}
 private void aboutPage(){LinearLayout help=section(null);row(help,"系统键盘设置","",()->startActivity(new Intent(Settings.ACTION_INPUT_METHOD_SETTINGS)));row(help,"开源许可","",this::openLicenses);row(help,"关于灵鹤输入法",versionName(),()->Ui.dialog(new AlertDialog.Builder(this).setTitle("灵鹤输入法 "+versionName()).setMessage("本机离线输入。附近文字仅临时用于本机联想。活动归档默认关闭，需另行同意后才上传所选来源的完整明文。\n\n开源组件许可随安装包提供。仅在你配置并开启同步后连接HTTPS中继；相机仅用于App内扫码，图像不上传。\n\n适配设备：vivo S50、Sony Xperia 5 III").setNeutralButton("开源许可",(dialog,which)->openLicenses()).setPositiveButton("好",null).create()));}
 private void refreshKeyboardStatus(){if(status==null||activate==null)return;boolean available=enabled();boolean selected=String.valueOf(Settings.Secure.getString(getContentResolver(),Settings.Secure.DEFAULT_INPUT_METHOD)).startsWith(getPackageName()+"/");status.setText(selected?"当前正在使用":available?"键盘已启用":"键盘尚未启用");activate.setText(available?"切换键盘":"启用键盘");}
 @Override public boolean onOptionsItemSelected(MenuItem item){if(item.getItemId()==android.R.id.home){showPage(HOME);return true;}return super.onOptionsItemSelected(item);}
 @Override public void onBackPressed(){if(!HOME.equals(page)){showPage(HOME);return;}super.onBackPressed();}
 @Override protected void onDestroy(){SettingsScreen.releaseBack(this,pageBack);pageBack=null;super.onDestroy();}
 private boolean enabled(){for(InputMethodInfo info:((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).getEnabledInputMethodList())if(info.getPackageName().equals(getPackageName()))return true;return false;}
 @Override protected void onResume(){super.onResume();SyncJob.schedule(this);refreshKeyboardStatus();}
 private LinearLayout section(String title){if(title!=null){TextView label=text(title,13,Ui.muted(this));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(dp(4),dp(22),0,dp(8));content.addView(label,lp);}LinearLayout box=new LinearLayout(this);box.setOrientation(1);Ui.panel(box);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);if(title==null)lp.topMargin=dp(16);content.addView(box,lp);return box;}
 private TextView row(LinearLayout box,String title,String detail,Runnable action){LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(dp(16),dp(10),dp(16),dp(10));line.setMinimumHeight(dp(52));line.addView(text(title,16,Ui.text(this)),new LinearLayout.LayoutParams(0,-2,1));TextView value=text(detail,14,Ui.muted(this));value.setTag("value");line.addView(value);TextView arrow=text("  ›",23,Ui.muted(this));line.addView(arrow);Ui.pressable(line,Ui.surface(this),12);line.setFocusable(true);line.setOnClickListener(v->action.run());box.addView(line,new LinearLayout.LayoutParams(-1,-2));return value;}
 private String feedbackLabel(){String value=prefs.getString("feedback","light");return value.equals("off")?"关闭":value.equals("strong")?"强":"轻";}
 private void choice(String title,String[] labels,int selected,java.util.function.IntConsumer action){RadioGroup group=new RadioGroup(this);group.setPadding(dp(12),dp(2),dp(12),dp(8));for(int i=0;i<labels.length;i++){RadioButton radio=new RadioButton(this);radio.setId(2000+i);radio.setText(labels[i]);radio.setTextSize(17);radio.setTextColor(Ui.text(this));radio.setPadding(dp(12),0,dp(12),0);group.addView(radio,new RadioGroup.LayoutParams(-1,dp(52)));}group.check(2000+selected);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title).setView(group).setNegativeButton("取消",null).create();group.setOnCheckedChangeListener((v,id)->{if(id>=2000&&id<2000+labels.length){action.accept(id-2000);dialog.dismiss();}});Ui.dialog(dialog);}
 private void chooseLayout(){choice("中文布局",new String[]{"九宫格","26 键"},prefs.getBoolean("nine",true)?0:1,index->{prefs.edit().putBoolean("nine",index==0).apply();layoutValue.setText(index==0?"九宫格":"26 键");});}
 private void choosePosition(){choice("拼音显示位置",new String[]{"键盘内","文本框内"},prefs.getBoolean("inline",false)?1:0,index->{prefs.edit().putBoolean("inline",index==1).apply();inlineValue.setText(index==1?"文本框内":"键盘内");});}
 private void chooseFeedback(){String current=prefs.getString("feedback","light");String[] values={"off","light","strong"};choice("按键触感",new String[]{"关闭","轻","强"},current.equals("off")?0:current.equals("strong")?2:1,index->{prefs.edit().putString("feedback",values[index]).apply();feedbackValue.setText(feedbackLabel());});}
 private void heightDialog(){LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(18),dp(12),dp(18),dp(8));TextView value=text(prefs.getInt("height",58)+"",20,Ui.text(this));value.setGravity(Gravity.CENTER);body.addView(value);SeekBar slider=new SeekBar(this);slider.setMax(30);slider.setProgress(prefs.getInt("height",58)-46);body.addView(slider,new LinearLayout.LayoutParams(-1,dp(52)));slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int n,boolean user){value.setText(String.valueOf(n+46));}});Ui.dialog(new AlertDialog.Builder(this).setTitle("键盘高度").setView(body).setNegativeButton("取消",null).setPositiveButton("完成",(d,w)->{int n=46+slider.getProgress();prefs.edit().putInt("height",n).apply();heightValue.setText(String.valueOf(n));}).create());}
 private void symbolsDialog(){LinearLayout body=new LinearLayout(this);body.setPadding(dp(18),0,dp(18),0);String[] defaults={"，","。","！","？"};EditText[] values=new EditText[4];for(int i=0;i<4;i++){values[i]=new EditText(this);values[i].setSingleLine();values[i].setText(prefs.getString("rail"+i,defaults[i]));body.addView(values[i],new LinearLayout.LayoutParams(0,dp(56),1));}AlertDialog dialog=new AlertDialog.Builder(this).setTitle("常用符号").setView(body).setNegativeButton("取消",null).setPositiveButton("完成",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{android.content.SharedPreferences.Editor edit=prefs.edit();for(int i=0;i<4;i++){String text=values[i].getText().toString().trim();if(text.isEmpty()||text.codePointCount(0,text.length())>4){values[i].setError("请输入 1–4 个字符");return;}edit.putString("rail"+i,text);}edit.apply();dialog.dismiss();}));Ui.dialog(dialog);}
}
